```rust
//! A minimal, dependency-free JSON parser (M8).
//!
//! strictix's blessed dependencies are serde + toml, and only inside the
//! CLI crate. The core crate parses `options.json` (nixpkgs schema data)
//! by hand, with this module. It implements the full JSON grammar:
//! objects, arrays, strings with escapes (including `\uXXXX` surrogate
//! pairs), numbers, `true`/`false`/`null`, and arbitrary whitespace.
//! Trailing non-whitespace content is rejected.
//!
//! The parser never panics: every malformed input yields a [`JsonError`]
//! carrying a message and the byte offset where the problem was detected.

/// A parsed JSON value.
///
/// Objects keep their entries in insertion order as a `Vec` of key/value
/// pairs; duplicate keys are kept (both entries) per the contract.
#[derive(Clone, Debug, PartialEq)]
pub enum JsonValue {
    /// `null`.
    Null,
    /// `true` or `false`.
    Bool(bool),
    /// A JSON number, stored as `f64`.
    Number(f64),
    /// A JSON string, decoded (escapes and `\uXXXX` resolved) to UTF-8.
    String(String),
    /// A JSON array.
    Array(Vec<JsonValue>),
    /// A JSON object; entries in source order.
    Object(Vec<(String, JsonValue)>),
}

/// A JSON parse failure: a human-readable message plus the byte offset in
/// the input where the error was detected.
#[derive(Debug, PartialEq, Eq)]
pub struct JsonError {
    /// What went wrong.
    pub message: String,
    /// Byte offset into the input where the error was detected.
    pub offset: usize,
}

impl JsonValue {
    /// Parse a complete JSON document from `input`.
    ///
    /// ...
    pub fn parse(input: &str) -> Result<JsonValue, JsonError> {
        let mut p = Parser { input, pos: 0 };
        p.skip_ws();
        let value = p.value()?;
        p.skip_ws();
        if p.peek_byte().is_some() {
            return Err(p.error("trailing content"));
        }
        Ok(value)
    }

    /// Object lookup: the first entry whose key equals `key`.
    #[must_use]
    pub fn get(&self, key: &str) -> Option<&JsonValue> {
        match self {
            JsonValue::Object(entries) => {
                entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
            }
            _ => None,
        }
    }

    /// This value as a string, if it is one.
    #[must_use]
    pub fn as_str(&self) -> Option<&str> {
        match self {
            JsonValue::String(s) => Some(s),
            _ => None,
        }
    }

    /// This value as a bool, if it is one.
    #[must_use]
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            JsonValue::Bool(b) => Some(*b),
            _ => None,
        }
    }

    /// This value as an array, if it is one.
    #[must_use]
    pub fn as_array(&self) -> Option<&[JsonValue]> {
        match self {
            JsonValue::Array(items) => Some(items),
            _ => None,
        }
    }

    /// This value as an object's entries (insertion order), if it is one.
    #[must_use]
    pub fn as_object(&self) -> Option<&[(String, JsonValue)]> {
        match self {
            JsonValue::Object(entries) => Some(entries),
            _ => None,
        }
    }
}
