                }
                _ => {
                    // Copy a full UTF-8 character (possibly multi-byte).
                    let ch = self.input[self.pos..].chars().next().expect("valid utf-8 boundary");
                    out.push(ch);
                    self.pos += ch.len_utf8();
                }
            }
        }
    }
