    fn unicode_escape(&mut self, out: &mut String) -> Result<(), JsonError> {
        let cp = self.hex4()?;
        match cp {
            0xD800..=0xDBFF => {
                // High surrogate: must be immediately followed by a low
                // surrogate escape, else the pair is unpaired.
                if self.peek_byte() == Some(b'\\') {
                    self.pos += 1;
                    if self.peek_byte() == Some(b'u') {
                        self.pos += 1;
                        let low = self.hex4()?;
                        if (0xDC00..=0xDFFF).contains(&low) {
                            let combined = 0x1_0000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                            let ch = char::from_u32(combined).expect("surrogate pair is a scalar");
                            out.push(ch);
                            return Ok(());
                        }
                    }
                }
                Err(self.error("unpaired surrogate"))
            }
            0xDC00..=0xDFFF => Err(self.error("unpaired surrogate")),
            _ => {
                match char::from_u32(cp) {
                    Some(ch) => out.push(ch),
                    None => return Err(self.error("invalid escape")),
                }
                Ok(())
            }
        }
    }

    fn hex4(&mut self) -> Result<u32, JsonError> {
        let mut value = 0u32;
        for _ in 0..4 {
            let Some(b) = self.peek_byte() else {
                return Err(self.error("unterminated string"));
            };
            let digit = match b {
                b'0'..=b'9' => u32::from(b - b'0'),
                b'a'..=b'f' => u32::from(b - b'a' + 10),
                b'A'..=b'F' => u32::from(b - b'A' + 10),
                _ => return Err(self.error("invalid escape")),
            };
            value = value * 16 + digit;
            self.pos += 1;
        }
        Ok(value)
    }
```

