            }
            // Lone low surrogate.
            0xDC00..=0xDFFF => Err(self.error("unpaired surrogate")),
            _ => match char::from_u32(code_point) {
                Some(ch) => {
                    out.push(ch);
                    Ok(())
                }
                // Unreachable: 4 hex digits are at most 0xFFFF and
                // surrogates are handled above.
                None => Err(self.error("invalid escape")),
            },
        }
